curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"WEB-1\") { id identifier title url createdAt team { key name } state { name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issues(first: 100) { nodes { id identifier title createdAt team { key name } state { name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(input: { id: \"i-web-1\", createdAt: \"2026-08-15T00:00:00\" }) { success issue { id identifier createdAt } } }"
  }'
